    useEffect(() => {if (!refreshRequested) return; if (dirty) {setRefreshRequested(false); setNotice('填写内容已保留，请先保存或放弃，再刷新资料。'); return;} if (blocked) return; setRefreshRequested(false); void run(refresh);}, [refreshRequested, dirty, blocked]);
    async function mutate(op: ProductionMutation['op'], input: Record<string, unknown>, token = snapshot?.editToken) {if (!token) return; const next = await invoke('mutateProduction', {op, input: {...input, expectedToken: token}, mutationId: uid()}); setSnapshot(next); return next;}
    async function start(kind: ProductionTask['kind'], title: string, text: string, accountId?: string, collectComments = false) {const result = await invoke('startProductionTask', {kind, title, prompt: text, mode, comments: collectComments, ...(accountId ? {accountId} : {})}); setSnapshot(result.snapshot); setNotice(result.opened ? '已打开助手。请在助手中选模型并手动提交，结果回传后还需验收。' : result.message ?? '任务已创建，请在任务列表继续打开助手。');}
